<?php require_once 'config.php'; $logo='https://i.ibb.co/8LJmm2FH/20260904-033616.png'; $handoffToken=preg_replace('/[^a-f0-9]/i','',(string)($_GET['handoff']??'')); $handoff=getKeyHandoff($handoffToken); $payload=is_array($handoff['payload']??null)?$handoff['payload']:[]; $app=$payload['app_name']??'HEX PROTOCOL'; $duration=$payload['duration_value']??'5'; $finalUrl=($handoff&&$handoffToken!=='')?buildPublicUrl('complete.php',['handoff'=>$handoffToken,'sig'=>handoffSignature($handoffToken)]):''; $shortResult=$finalUrl!==''?shortenWithVplink($finalUrl,'hex_'.substr($handoffToken,0,10)):['success'=>false]; $shortUrl=$shortResult['success']?$shortResult['url']:''; $vplink=vplinkSettings(); if($shortUrl&&!empty($_SESSION['key_handoffs'][$handoffToken])){$_SESSION['key_handoffs'][$handoffToken]['shortener_started']=true;$_SESSION['key_handoffs'][$handoffToken]['shortener_started_at']=time();} $fallback=!$shortUrl&&!$vplink['block_without_shortener']&&$handoff; if($fallback)$_SESSION['vplink_returns'][$handoffToken]=time(); $destination=$shortUrl?:($fallback?buildPublicUrl('generated.php',['handoff'=>$handoffToken,'sig'=>handoffSignature($handoffToken)]):''); $error=(!$handoff||$destination==='')?'Secure handoff unavailable. Generate a new key and try again.':($shortUrl?'':'The secure task is temporarily unavailable.'); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HEX PROTOCOL — Secure Task</title><link rel="icon" href="<?php echo htmlspecialchars($logo,ENT_QUOTES); ?>"><link rel="stylesheet" href="public.css"><?php if($destination!==''): ?><meta http-equiv="refresh" content="2;url=<?php echo htmlspecialchars($destination,ENT_QUOTES); ?>"><?php endif; ?></head><body><div class="site-shell"><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.php"><img class="brand-logo" src="<?php echo htmlspecialchars($logo,ENT_QUOTES); ?>" alt=""><span>HEX PROTOCOL</span></a></div></header><main class="page-wrap"><section class="result-panel panel"><div class="panel-head"><div><h2><?php echo $handoff?'Complete secure task':'Handoff blocked'; ?></h2><p><?php echo $handoff?'Your key page will open automatically when the task is complete.':'Generate a new key to start again.'; ?></p></div><span class="online-badge">SECURE</span></div><div class="form-body"><div class="status-card" style="margin:0 0 16px;max-width:none"><span class="status-dot"></span><div><strong><?php echo htmlspecialchars($error?:'Application: '.$app.' · '.$duration.' hours'); ?></strong><p>Generated → Complete task → Receive key</p></div></div><?php if($destination!==''): ?><div class="cooldown">↻ Continuing automatically…</div><?php else: ?><a class="btn btn-primary btn-block" href="index.php">Generate a new key</a><?php endif; ?></div></section></main><footer class="footer"><span>© 2018–<?php echo date('Y'); ?> HEX PROTOCOL</span></footer></div><?php if($destination!==''): ?><script>setTimeout(()=>location.href=<?php echo json_encode($destination); ?>,2000)</script><?php endif; ?></body></html>
